def main():
    db_key = os.getenv('DB_KEY', 'HO').strip().upper()
    set_active_db_key(db_key)
    loc_info = get_location_info_by_dbkey(db_key)
    raw = (loc_info or {}).get('locationcode')
    try:
        locationcode = int(raw) if isinstance(raw, (int, float)) else int(float(str(raw).strip())) if raw is not None else None
    except (ValueError, TypeError):
        locationcode = None
    t = CHART_OF_ACCOUNTS_TABLE
    sql = f'\n        INSERT INTO {t} (ACCOUNT_ID, CODE, NAME, TYPE, PARENT_ID, IS_POSTABLE, CURRENCY, STATUS, COMPANY_ID, BRANCH_ID, LOCATIONCODE)\n        VALUES (:aid, :code, :name, :typ, :parent_id, :is_postable, :currency, :status, NULL, NULL, :locationcode)\n    '
    inserted = 0
    skipped = 0
    with _get_connection() as conn:
        with conn.cursor() as cur:
            for row in SEED_ROWS:
                try:
                    cur.execute(sql, {'aid': row['ACCOUNT_ID'], 'code': row['CODE'], 'name': row['NAME'], 'typ': row['TYPE'], 'parent_id': row['PARENT_ID'], 'is_postable': row['IS_POSTABLE'], 'currency': row['CURRENCY'], 'status': row['STATUS'], 'locationcode': locationcode})
                    inserted += 1
                except Exception as e:
                    if 'unique constraint' in str(e).lower() or 'ORA-00001' in str(e):
                        skipped += 1
                        print(f"Skip (exists): {row['CODE']} {row['NAME']}")
                    else:
                        print(f"Error inserting {row['CODE']} {row['NAME']}: {e}")
                        raise
        conn.commit()
    print(f'Done. Inserted: {inserted}, Skipped (already exist): {skipped}')
if __name__ == '__main__':
    main()
